function validateConstraintDefinition(source,w,direction,rule,templateVersion='flat-v1-draft'){if(!rule)return;const encode=sample=>{const value=String(w.type||'').endsWith('[]')?[sample]:sample;const field={address:address(w.address),type:w.type,scale:number(w.scale)??1,offset:number(w.offset)??0,maxBytes:number(w.maxBytes)||undefined,maxCount:number(w.maxCount)||undefined,minRaw:rawRange(source,w)?.[0],maxRaw:rawRange(source,w)?.[1],constraints:{[direction]:rule},value};const spec=direction==='write'?{templateVersion,sid:8,operation:'write',role:'request',messageId:1,fields:[field]}:{templateVersion,sid:8,operation:'report',role:'report',messageId:1,fields:[field]};return BLEProto.encodePDU(spec);};if(rule.allowedValues?.length)for(const sample of rule.allowedValues){try{encode(sample);}catch(e){throw Object.assign(new Error('数值约束定义不合法或允许值与其他规则冲突：'+e.message),{code:'ENGINEERING_CONSTRAINT'});}}else{const candidates=[rule.maximum,rule.minimum,rule.stepOrigin,'0'].filter(x=>x!==undefined);let passed=false,last=null;for(const sample of candidates){try{encode(sample);passed=true;break;}catch(e){last=e;if(!['ENGINEERING_RANGE','ENGINEERING_STEP','ENGINEERING_ALLOWED_VALUES'].includes(e.code))throw Object.assign(new Error('数值约束定义不合法：'+e.message),{code:'ENGINEERING_CONSTRAINT'});}}if(!passed)throw Object.assign(new Error('数值约束定义无法形成可编码值：'+(last?.message||'约束冲突')),{code:'ENGINEERING_CONSTRAINT'});}}
